INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7324603, 1143186, 102278, '<td valign="top">I like the colours in this splash. Water drops are one of those common photography genres that often get slated on DPC but i often do like the sculptural beauty of them. This could be sharper of course but i guess you already know that. Regardless, it''s a nice image.</td>', 'I like the colours in this splash. Water drops are one of those common photography genres that often get slated on DPC but i often do like the sculptural beauty of them. This could be sharper of course but i guess you already know that. Regardless, it''s a nice image.', '2015-03-07 06:36:23.000000', NULL, 1),
(7324604, 1142746, 102278, '<td valign="top">Really like the textures and colour.</td>', 'Really like the textures and colour.', '2015-03-07 06:36:42.000000', NULL, 1),
(7324605, 1141201, 102278, '<td valign="top">I do like a duck picture.</td>', 'I do like a duck picture.', '2015-03-07 06:37:13.000000', NULL, 1),
(7324609, 1143032, 156466, '<td valign="top">Powerful, but oversharpened around the rocks and the person.  Remove the halo and this would have scored nicely with me.</td>', 'Powerful, but oversharpened around the rocks and the person.  Remove the halo and this would have scored nicely with me.', '2015-03-07 08:15:44.000000', NULL, 1),
(7324611, 1143024, 156466, '<td valign="top">Love both the photo and the treatment, even if the skewed lines have my OCD tweeking.</td>', 'Love both the photo and the treatment, even if the skewed lines have my OCD tweeking.', '2015-03-07 08:17:55.000000', NULL, 1),
(7324612, 1143121, 156466, '<td valign="top">Made me smile as soon as it came up.</td>', 'Made me smile as soon as it came up.', '2015-03-07 08:19:03.000000', NULL, 1),
(7324613, 1143020, 156466, '<td valign="top">Nice photo but I''m not fond of the over-soft treatment.</td>', 'Nice photo but I''m not fond of the over-soft treatment.', '2015-03-07 08:19:48.000000', NULL, 1),
(7324614, 1142903, 156466, '<td valign="top">Great capture.  If only you''d gotten the full horse on the right. I might have cropped in to the saddle front to give less of a feeling of "just missed".</td>', 'Great capture.  If only you''d gotten the full horse on the right. I might have cropped in to the saddle front to give less of a feeling of "just missed".', '2015-03-07 08:24:05.000000', NULL, 1),
(7324615, 1143031, 156466, '<td valign="top">Lovely vista, but it feels overprocessed.</td>', 'Lovely vista, but it feels overprocessed.', '2015-03-07 08:26:14.000000', NULL, 1),
(7324616, 1143126, 156466, '<td valign="top">Beautiful, but it feels like it''s leaning left.</td>', 'Beautiful, but it feels like it''s leaning left.', '2015-03-07 08:27:10.000000', NULL, 1),
(7324617, 1143069, 156466, '<td valign="top">Great moment</td>', 'Great moment', '2015-03-07 08:27:57.000000', NULL, 1),
(7324618, 1142553, 16148, '<td valign="top">Very nice documentary shot.  The scale is amazing.</td>', 'Very nice documentary shot.  The scale is amazing.', '2015-03-07 08:29:54.000000', NULL, 1),
(7324619, 1143127, 156466, '<td valign="top">Watch the over-sharpening halos.  Easy to fix, and they just kill this otherwise lovely shot. Turht is, the more I look the more the entire shot seems over sharpened/structured.  A re-edit could yield something great.</td>', 'Watch the over-sharpening halos.  Easy to fix, and they just kill this otherwise lovely shot. Turht is, the more I look the more the entire shot seems over sharpened/structured.  A re-edit could yield something great.', '2015-03-07 08:30:14.000000', NULL, 1),
(7324620, 1141377, 16148, '<td valign="top">Nicely spotted!  Make the most out of a tough situation.</td>', 'Nicely spotted!  Make the most out of a tough situation.', '2015-03-07 08:31:24.000000', NULL, 1),
(7324621, 1141683, 156466, '<td valign="top">I suspect this looks better against a darker background, but it''s too dark for me.</td>', 'I suspect this looks better against a darker background, but it''s too dark for me.', '2015-03-07 08:31:38.000000', NULL, 1),
(7324622, 1143172, 16148, '<td valign="top">Terrific POV!  Really nicely composed shot.</td>', 'Terrific POV!  Really nicely composed shot.', '2015-03-07 08:31:58.000000', NULL, 1),
(7324623, 1143177, 16148, '<td valign="top">Excellent!  Rain or shine.</td>', 'Excellent!  Rain or shine.', '2015-03-07 08:32:29.000000', NULL, 1),
(7324624, 1142738, 156466, '<td valign="top">(not voting) I like the capture, but not so much treatment.  I''m thinking B&amp;W would work to remove some of the color distractions on the edges.</td>', '(not voting) I like the capture, but not so much treatment.  I''m thinking B&W would work to remove some of the color distractions on the edges.', '2015-03-07 08:33:48.000000', NULL, 1),
(7324625, 1142857, 16148, '<td valign="top">Beautiful high contrast shot.  Organic lines of the tree with modern, right angle, architecture behind.</td>', 'Beautiful high contrast shot.  Organic lines of the tree with modern, right angle, architecture behind.', '2015-03-07 08:33:52.000000', NULL, 1),
(7324626, 1142333, 16148, '<td valign="top">I like the warm tones for February.  You given us hope.</td>', 'I like the warm tones for February.  You given us hope.', '2015-03-07 08:34:31.000000', NULL, 1),
(7324627, 1143005, 156466, '<td valign="top">All I can think of is how cool this would be to shoot at night with the right lighting.</td>', 'All I can think of is how cool this would be to shoot at night with the right lighting.', '2015-03-07 08:35:09.000000', NULL, 1),
(7324628, 1142980, 16148, '<td valign="top">Amazingly juxtaposed tree and ruins.  Nice find and well captured.</td>', 'Amazingly juxtaposed tree and ruins.  Nice find and well captured.', '2015-03-07 08:35:24.000000', NULL, 1),
(7324629, 1143069, 16148, '<td valign="top">Genuine moment!  Really, what photography is all about.</td>', 'Genuine moment!  Really, what photography is all about.', '2015-03-07 08:36:34.000000', NULL, 1),
(7324630, 1142696, 16148, '<td valign="top">Love the image but not the title.  Saying he''s retired says nothing about who he is.  Beautiful natural light and environment.  His hand on his straw hat is a very nice touch.  A beautiful portrait! 8</td>', 'Love the image but not the title.  Saying he''s retired says nothing about who he is.  Beautiful natural light and environment.  His hand on his straw hat is a very nice touch.  A beautiful portrait! 8', '2015-03-07 08:36:37.000000', NULL, 1),
(7324631, 1142904, 16148, '<td valign="top">Something positive.  Thanks</td>', 'Something positive.  Thanks', '2015-03-07 08:37:02.000000', NULL, 1),
(7324632, 1143048, 156466, '<td valign="top">Really like this one.  My OCD wants that miniscule bit of lens distortion removed so the brick lines at the top are straight, but that''s just picking nits.  8</td>', 'Really like this one.  My OCD wants that miniscule bit of lens distortion removed so the brick lines at the top are straight, but that''s just picking nits.  8', '2015-03-07 08:37:14.000000', NULL, 1),
(7324633, 1142426, 156466, '<td valign="top">I might have removed the branch and flirted with a DQ (I think you would have been OK).  Otherwise lovely.</td>', 'I might have removed the branch and flirted with a DQ (I think you would have been OK).  Otherwise lovely.', '2015-03-07 08:38:21.000000', NULL, 1),
(7324634, 1143024, 63218, '<td valign="top">WOW. I''m getting a lot of elemental life energy from this, even  before I figured out the frogs. This is a truly unique photo. Thanks for posting it.</td>', 'WOW. I''m getting a lot of elemental life energy from this, even  before I figured out the frogs. This is a truly unique photo. Thanks for posting it.', '2015-03-07 08:38:58.000000', NULL, 1),
(7324635, 1143110, 156466, '<td valign="top">The tethered balloons juxtaposing the chains on the lights makes this one for me.  Well done.</td>', 'The tethered balloons juxtaposing the chains on the lights makes this one for me.  Well done.', '2015-03-07 08:40:44.000000', NULL, 1),
(7324636, 1143158, 16148, '<td valign="top">She appears to be so tiny and frail.  For some reason retired horse jockey comes to mind.  Very nice!</td>', 'She appears to be so tiny and frail.  For some reason retired horse jockey comes to mind.  Very nice!', '2015-03-07 08:41:13.000000', NULL, 1),
(7324637, 1141655, 156466, '<td valign="top">Love the foreground, not so much the background.</td>', 'Love the foreground, not so much the background.', '2015-03-07 08:41:24.000000', NULL, 1),
(7324638, 1143144, 16148, '<td valign="top">Interest piqued.  bump 8</td>', 'Interest piqued.  bump 8', '2015-03-07 08:44:23.000000', NULL, 1),
(7324639, 1142421, 16148, '<td valign="top">Beautifully done!</td>', 'Beautifully done!', '2015-03-07 08:45:37.000000', NULL, 1),
(7324640, 1142825, 156466, '<td valign="top">The machinery to the left seemed very distracting until I realized they were the church bells.  The breaks in the snow on the roof makes for the most interesting shapes.  For a second I thought it was some sort of Asian character texture.  Very cool shot.</td>', 'The machinery to the left seemed very distracting until I realized they were the church bells.  The breaks in the snow on the roof makes for the most interesting shapes.  For a second I thought it was some sort of Asian character texture.  Very cool shot.', '2015-03-07 08:46:46.000000', NULL, 1),
(7324642, 1143185, 156466, '<td valign="top">Horizon needs fixing.</td>', 'Horizon needs fixing.', '2015-03-07 08:47:48.000000', NULL, 1),
(7324644, 1141891, 156466, '<td valign="top">Feels over-cooked for such a lovely scene.</td>', 'Feels over-cooked for such a lovely scene.', '2015-03-07 08:49:48.000000', NULL, 1),
(7324645, 1142826, 156466, '<td valign="top">Maybe one or the other - MAYBE... but not both.</td>', 'Maybe one or the other - MAYBE... but not both.', '2015-03-07 08:51:08.000000', NULL, 1),
(7324646, 1143117, 156466, '<td valign="top">Love the photo, hate the title.</td>', 'Love the photo, hate the title.', '2015-03-07 08:52:24.000000', NULL, 1),
(7324647, 1142989, 156466, '<td valign="top">I can''t seem to twist my mind around how you managed this shot without a processing DQ given what I can see through it.  Very cool shot (pun only slightly intended).</td>', 'I can''t seem to twist my mind around how you managed this shot without a processing DQ given what I can see through it.  Very cool shot (pun only slightly intended).', '2015-03-07 08:54:00.000000', NULL, 1),
(7324648, 1143172, 179608, '<td valign="top">Very beautiful B&amp;W landscape; essential and minimal but fascinating</td>', 'Very beautiful B&W landscape; essential and minimal but fascinating', '2015-03-07 08:58:26.000000', NULL, 1),
(7324649, 1143125, 156466, '<td valign="top">Really love the building.  I might have cropped in a bit at the right to remove that one bright spot at the sidewalk, and possibly cloned out the thing in the bottom right corner.  Otherwise very nice. 7</td>', 'Really love the building.  I might have cropped in a bit at the right to remove that one bright spot at the sidewalk, and possibly cloned out the thing in the bottom right corner.  Otherwise very nice. 7', '2015-03-07 08:59:52.000000', NULL, 1),
(7324650, 1142817, 83149, '<td valign="top">Lovely shot, but the toe should not have been cut off.</td>', 'Lovely shot, but the toe should not have been cut off.', '2015-03-07 09:00:35.000000', NULL, 1),
(7324651, 1143009, 156466, '<td valign="top">Lovely, but there''s some dark haloing that needs fixing around the thickest branches throughout which gets very distracting.</td>', 'Lovely, but there''s some dark haloing that needs fixing around the thickest branches throughout which gets very distracting.', '2015-03-07 09:01:06.000000', NULL, 1),
(7324652, 1143145, 156466, '<td valign="top">They always seem to get at least one branch between themselves and the camera, don''t they?</td>', 'They always seem to get at least one branch between themselves and the camera, don''t they?', '2015-03-07 09:02:32.000000', NULL, 1),
(7324653, 1142932, 156466, '<td valign="top">Highlights feel just a little too pulled back - just a tad too low key.  Great capture.  Focus stacked?</td>', 'Highlights feel just a little too pulled back - just a tad too low key.  Great capture.  Focus stacked?', '2015-03-07 09:04:56.000000', NULL, 1),
(7324654, 1143002, 156466, '<td valign="top">Sure wish the guy was also looking at the camera.</td>', 'Sure wish the guy was also looking at the camera.', '2015-03-07 09:05:48.000000', NULL, 1),
(7324655, 1142846, 179608, '<td valign="top">A beautiful landscape in a nice composition; perfect the arc of the tree that covers the sun</td>', 'A beautiful landscape in a nice composition; perfect the arc of the tree that covers the sun', '2015-03-07 09:06:06.000000', NULL, 1),
(7324656, 1142275, 83149, '<td valign="top">I thought you might enter this one.  Great lighting and the B&amp;W really works.</td>', 'I thought you might enter this one.  Great lighting and the B&W really works.', '2015-03-07 09:07:05.000000', NULL, 1),
(7324657, 1143149, 156466, '<td valign="top">That branch at the left is just too distracting for me.  Otherwise nicely shot and processed.</td>', 'That branch at the left is just too distracting for me.  Otherwise nicely shot and processed.', '2015-03-07 09:07:16.000000', NULL, 1),
(7324658, 1142713, 83149, '<td valign="top">Great subject, but a little soft and way too small.</td>', 'Great subject, but a little soft and way too small.', '2015-03-07 09:08:09.000000', NULL, 1),
(7324659, 1143019, 179608, '<td valign="top">beautiful landscape in night scene; the lighthouse sentinel is a perfect reference point</td>', 'beautiful landscape in night scene; the lighthouse sentinel is a perfect reference point', '2015-03-07 09:08:13.000000', NULL, 1),
(7324661, 1143024, 35804, '<td valign="top">I''m back to comment...I gave this a 10. This is one of my favorites for so many reasons. It took me a minute to figure out what I was looking at. I enjoy looking at this as an abstract...all these great shapes and color. Then it hit me...FROGS! That made everything even better. It''s funny how my wanting to see this strictly as abstract kept me from seeing the frogs...I do wish I could hear this.</td>', 'I''m back to comment...I gave this a 10. This is one of my favorites for so many reasons. It took me a minute to figure out what I was looking at. I enjoy looking at this as an abstract...all these great shapes and color. Then it hit me...FROGS! That made everything even better. It''s funny how my wanting to see this strictly as abstract kept me from seeing the frogs...I do wish I could hear this.', '2015-03-07 09:10:06.000000', NULL, 1),
(7324662, 1142553, 83149, '<td valign="top">I would have preferred this without the model.</td>', 'I would have preferred this without the model.', '2015-03-07 09:10:49.000000', NULL, 1),
(7324663, 1143145, 35804, '<td valign="top">Back to comment...he, or she, is a cute little snow monster. what a lovely catch this is.</td>', 'Back to comment...he, or she, is a cute little snow monster. what a lovely catch this is.', '2015-03-07 09:11:42.000000', NULL, 1),
(7324664, 1143048, 35804, '<td valign="top">I love it when things come together like this.</td>', 'I love it when things come together like this.', '2015-03-07 09:12:20.000000', NULL, 1),
(7324665, 1142829, 179608, '<td valign="top">very nice portrait, my compliments</td>', 'very nice portrait, my compliments', '2015-03-07 09:13:24.000000', NULL, 1),
(7324667, 1142848, 179608, '<td valign="top">A great point of view from the base of poiint of Rialto; magnificent shot with beautiful colours</td>', 'A great point of view from the base of poiint of Rialto; magnificent shot with beautiful colours', '2015-03-07 09:15:39.000000', NULL, 1),
(7324669, 1142999, 179608, '<td valign="top">magnificent B&amp;W</td>', 'magnificent B&W', '2015-03-07 09:17:02.000000', NULL, 1),
(7324670, 1143117, 35804, '<td valign="top">This is the sort of thing I love. We see the "things", but the things become something else. I let the shapes and color carry me away for a while, then I wonder all the whys...I''m not terribly set on the orientation of the actual image, I like it tipped up or down perhaps slightly more, but it makes things interesting to have such a versatile photograph. And I swear, touches of pink make everything better in the world. Oh, and that green leaf resting atop the pink jacket...perfection.</td>', 'This is the sort of thing I love. We see the "things", but the things become something else. I let the shapes and color carry me away for a while, then I wonder all the whys...I''m not terribly set on the orientation of the actual image, I like it tipped up or down perhaps slightly more, but it makes things interesting to have such a versatile photograph. And I swear, touches of pink make everything better in the world. Oh, and that green leaf resting atop the pink jacket...perfection.', '2015-03-07 09:17:31.000000', NULL, 1),
(7324671, 1143105, 35804, '<td valign="top">...it''s a mystery...am I at sea, or am I trapped in a snowbound house. Either way it''s a good story.</td>', '...it''s a mystery...am I at sea, or am I trapped in a snowbound house. Either way it''s a good story.', '2015-03-07 09:18:29.000000', NULL, 1),
(7324673, 1143172, 35804, '<td valign="top">...cold little city locked in snow...nicely seen.  I remember winters in Chicago, walking down Jackson towards the lake...that wind went right through you no matter how much you tried to wrap up.</td>', '...cold little city locked in snow...nicely seen.  I remember winters in Chicago, walking down Jackson towards the lake...that wind went right through you no matter how much you tried to wrap up.', '2015-03-07 09:22:24.000000', NULL, 1),
(7324674, 1143122, 179608, '<td valign="top">Good landscape; for the perfect shot you''dd had to leave more space up for the sky</td>', 'Good landscape; for the perfect shot you''dd had to leave more space up for the sky', '2015-03-07 09:23:13.000000', NULL, 1),
(7324675, 1143007, 35804, '<td valign="top">...the warmth of both the light and tea make me smile, and wish I could have a taste.</td>', '...the warmth of both the light and tea make me smile, and wish I could have a taste.', '2015-03-07 09:23:29.000000', NULL, 1),
(7324676, 1143144, 35804, '<td valign="top">I hate when a painting looks at me like that...sitting up there in its frame giving everyone the stink eye. Nicely seen and thanks for the chuckle.</td>', 'I hate when a painting looks at me like that...sitting up there in its frame giving everyone the stink eye. Nicely seen and thanks for the chuckle.', '2015-03-07 09:25:35.000000', NULL, 1),
(7324677, 1143101, 35804, '<td valign="top">I love a good fluffy bird in snow shot...this is definitely one of them, very nice.</td>', 'I love a good fluffy bird in snow shot...this is definitely one of them, very nice.', '2015-03-07 09:26:36.000000', NULL, 1),
(7324678, 1143181, 179608, '<td valign="top">Great landscape, the distorsion is too much for my tastes but in this contest is not so disturbing</td>', 'Great landscape, the distorsion is too much for my tastes but in this contest is not so disturbing', '2015-03-07 09:27:23.000000', NULL, 1),
(7324679, 1141377, 35804, '<td valign="top">I can feel that wind and snow against my face...nicely captured.</td>', 'I can feel that wind and snow against my face...nicely captured.', '2015-03-07 09:28:31.000000', NULL, 1),
(7324680, 1142999, 35804, '<td valign="top">A really nice pup portrait. The light and B&amp;W conversion are super nice.</td>', 'A really nice pup portrait. The light and B&W conversion are super nice.', '2015-03-07 09:29:33.000000', NULL, 1),
(7324681, 1142333, 35804, '<td valign="top">...I honestly think trees are more lovely undressed...this helps prove my point.</td>', '...I honestly think trees are more lovely undressed...this helps prove my point.', '2015-03-07 09:31:10.000000', NULL, 1),
(7324682, 1142553, 35804, '<td valign="top">Oh good grief that must suck...the claustrophobia of it all. It makes for a cool photograph though doesn''t it?!</td>', 'Oh good grief that must suck...the claustrophobia of it all. It makes for a cool photograph though doesn''t it?!', '2015-03-07 09:32:28.000000', NULL, 1),
(7324683, 1143107, 35804, '<td valign="top">You''ve captured the catitude perfectly! I wouldn''t want to be on the other end of that stink eye...nope.</td>', 'You''ve captured the catitude perfectly! I wouldn''t want to be on the other end of that stink eye...nope.', '2015-03-07 09:34:20.000000', NULL, 1),
(7324684, 1143065, 35804, '<td valign="top">So true...and this looks like a perfect place for just that. I enjoy the simplicity of this scene..it''s nothing spectacular, and by that I mean there are no grand vistas with mountains or sea draped in the rising or falling sun. This is the often photographer ignored view, where the quiet and good things happen. Thanks for sharing your walk with us.</td>', 'So true...and this looks like a perfect place for just that. I enjoy the simplicity of this scene..it''s nothing spectacular, and by that I mean there are no grand vistas with mountains or sea draped in the rising or falling sun. This is the often photographer ignored view, where the quiet and good things happen. Thanks for sharing your walk with us.', '2015-03-07 09:39:08.000000', NULL, 1),
(7324686, 1143185, 35804, '<td valign="top">...how''d you get them line up like that? ...and those clouds to line up perfectly too? Nice catch!</td>', '...how''d you get them line up like that? ...and those clouds to line up perfectly too? Nice catch!', '2015-03-07 09:40:27.000000', NULL, 1),
(7324688, 1142592, 35804, '<td valign="top">This is one of those photographs that makes me wish I were there, at that moment, because I know that quiet pastel sunset must have been even better in person. The blanket of snow makes it even better.</td>', 'This is one of those photographs that makes me wish I were there, at that moment, because I know that quiet pastel sunset must have been even better in person. The blanket of snow makes it even better.', '2015-03-07 09:43:09.000000', NULL, 1),
(7324689, 1143171, 35804, '<td valign="top">Magical indeed! I want to try this on one of my trees now, but that is quite a spectacular specimen with its low long branches. The warm B&amp;W conversion was the perfect choice for this photograph..very nicely done.</td>', 'Magical indeed! I want to try this on one of my trees now, but that is quite a spectacular specimen with its low long branches. The warm B&W conversion was the perfect choice for this photograph..very nicely done.', '2015-03-07 09:46:48.000000', NULL, 1),
(7324690, 1142799, 35804, '<td valign="top">Ooo! Another owl...I love it!</td>', 'Ooo! Another owl...I love it!', '2015-03-07 09:47:41.000000', NULL, 1),
(7324692, 1143177, 35804, '<td valign="top">...and fresh. I really like this, this bit of suburban whimsy. It reminds me there is magic everywhere...we just have to open our eyes to it.</td>', '...and fresh. I really like this, this bit of suburban whimsy. It reminds me there is magic everywhere...we just have to open our eyes to it.', '2015-03-07 09:49:39.000000', NULL, 1),
(7324693, 1142621, 35804, '<td valign="top">I smiled, then I saw the title...and smiled even more...bumping to a 9.</td>', 'I smiled, then I saw the title...and smiled even more...bumping to a 9.', '2015-03-07 09:50:41.000000', NULL, 1),
(7324696, 1143106, 35804, '<td valign="top">I can take or leave sunset photographs..but this one, the way the gold gently coats everything...and those clouds...this one made me pause, and not want to move on to the next as I usually do. Thanks for the moment.</td>', 'I can take or leave sunset photographs..but this one, the way the gold gently coats everything...and those clouds...this one made me pause, and not want to move on to the next as I usually do. Thanks for the moment.', '2015-03-07 09:54:14.000000', NULL, 1),
(7324697, 1143058, 35804, '<td valign="top">...oh gosh...it''s so cute...cold...but so darn cute!</td>', '...oh gosh...it''s so cute...cold...but so darn cute!', '2015-03-07 09:55:21.000000', NULL, 1),
(7324698, 1143100, 35804, '<td valign="top">I have a devil cat like this, same coloring and everything...except I get this look before she wrecks a different sort of havoc.</td>', 'I have a devil cat like this, same coloring and everything...except I get this look before she wrecks a different sort of havoc.', '2015-03-07 09:57:45.000000', NULL, 1),
(7324699, 1143170, 35804, '<td valign="top">You know...I love the soft purple/lavender thing that''s happening here. It''s a bit of a daring choice, but it really works. I don''t think this would be nearly as interesting without it truth be told...vey nice.</td>', 'You know...I love the soft purple/lavender thing that''s happening here. It''s a bit of a daring choice, but it really works. I don''t think this would be nearly as interesting without it truth be told...vey nice.', '2015-03-07 09:59:29.000000', NULL, 1),
(7324701, 1142696, 35804, '<td valign="top">I love the "crunch" of this...the good crunchy crispy light, the kinship of the stone and wrinkles topped off with a really nice B&amp;W conversion make this an extra nice portrait. I also like that perhaps you''ve caught him mid sentence, or maybe not...there is conversation none the less.</td>', 'I love the "crunch" of this...the good crunchy crispy light, the kinship of the stone and wrinkles topped off with a really nice B&W conversion make this an extra nice portrait. I also like that perhaps you''ve caught him mid sentence, or maybe not...there is conversation none the less.', '2015-03-07 10:03:08.000000', NULL, 1),
(7324707, 1143122, 35804, '<td valign="top">The light is so full of warmth...but I know the truth...it''s cold out there. The tracks make this. Without them it would still be nice, but there tracks are that cherry on top sort of thing. The mist over the water is particularly nice....I love when that happens.</td>', 'The light is so full of warmth...but I know the truth...it''s cold out there. The tracks make this. Without them it would still be nice, but there tracks are that cherry on top sort of thing. The mist over the water is particularly nice....I love when that happens.', '2015-03-07 10:25:41.000000', NULL, 1),
(7324708, 1142172, 35804, '<td valign="top">I like to think of these sort of images as "eye fun". All the texture, shapes, color...like a playground for my eyeballs. I think that''s why I like catching them myself.</td>', 'I like to think of these sort of images as "eye fun". All the texture, shapes, color...like a playground for my eyeballs. I think that''s why I like catching them myself.', '2015-03-07 10:28:20.000000', NULL, 1),
(7324709, 1142904, 35804, '<td valign="top">The harmony between the comment and the shadow...it''s a good one. I love how the blue is running down to meet them all...nicely seen.</td>', 'The harmony between the comment and the shadow...it''s a good one. I love how the blue is running down to meet them all...nicely seen.', '2015-03-07 10:30:28.000000', NULL, 1),
(7324710, 1143069, 35804, '<td valign="top">Happy moments simply caught. This is the good stuff for sure.</td>', 'Happy moments simply caught. This is the good stuff for sure.', '2015-03-07 10:33:20.000000', NULL, 1),
(7324711, 1143140, 35804, '<td valign="top">...bumping to an 8. This is more than a photograph...it''s a feeling.</td>', '...bumping to an 8. This is more than a photograph...it''s a feeling.', '2015-03-07 10:34:30.000000', NULL, 1),
(7324712, 1141655, 35804, '<td valign="top">For some reason I love seeing photographs of where other people go for walks...maybe because I love walks myself? This looks like a good place for a walk. It''s interesting, at least to me...there are the not far from home walks, perhaps like this place, then there are the far from civilization sort of walks, I like those too. Maybe I''m weird to contemplate the idea of where and why people walk, but it''s intriguing.</td>', 'For some reason I love seeing photographs of where other people go for walks...maybe because I love walks myself? This looks like a good place for a walk. It''s interesting, at least to me...there are the not far from home walks, perhaps like this place, then there are the far from civilization sort of walks, I like those too. Maybe I''m weird to contemplate the idea of where and why people walk, but it''s intriguing.', '2015-03-07 10:40:01.000000', NULL, 1),
(7324714, 1143137, 35804, '<td valign="top">...you''re right..it is...the longer I look t this, the more interesting it becomes. Plus, the more I look at this, the more I want to pick those little bits of drieds out of the chicken wire...it''s a compulsion like bubble wrap.</td>', '...you''re right..it is...the longer I look t this, the more interesting it becomes. Plus, the more I look at this, the more I want to pick those little bits of drieds out of the chicken wire...it''s a compulsion like bubble wrap.', '2015-03-07 10:43:05.000000', NULL, 1),
(7324718, 1142826, 35804, '<td valign="top">I recognize the model from a previous challenge, which is fine. She''s lovely. I just have to admit that I would have given this a much higher score had it not been for the selective desaturation things happening here. Maybe it would have been slightly more pleasing with just the lips done, maybe...but the lips and the bauble are just too much. The blue bauble begs for my attention and I resent it for that.</td>', 'I recognize the model from a previous challenge, which is fine. She''s lovely. I just have to admit that I would have given this a much higher score had it not been for the selective desaturation things happening here. Maybe it would have been slightly more pleasing with just the lips done, maybe...but the lips and the bauble are just too much. The blue bauble begs for my attention and I resent it for that.', '2015-03-07 10:52:11.000000', NULL, 1),
(7324719, 1143127, 35804, '<td valign="top">I think it''s overcooked for my taste...the hills are glowing as if radioactive. The movement around the rocks is very nice though...maybe just a little less processing overall,  a lighter touch so to speak, as it is a nice scene.</td>', 'I think it''s overcooked for my taste...the hills are glowing as if radioactive. The movement around the rocks is very nice though...maybe just a little less processing overall,  a lighter touch so to speak, as it is a nice scene.', '2015-03-07 10:55:55.000000', NULL, 1),
(7324725, 1143179, 35804, '<td valign="top">I''m back to bump this up to an 8...no, 9. The control over the tonal scale is so nice as is the B&amp;W conversion. It''s also my fascination with where people go walking that causes a moment for pause as I make my way back through this February FS. I''m glad the person is there and I''m becoming fairly obsessed with the reflections in the water.</td>', 'I''m back to bump this up to an 8...no, 9. The control over the tonal scale is so nice as is the B&W conversion. It''s also my fascination with where people go walking that causes a moment for pause as I make my way back through this February FS. I''m glad the person is there and I''m becoming fairly obsessed with the reflections in the water.', '2015-03-07 11:01:37.000000', NULL, 1),
(7324728, 1142746, 35804, '<td valign="top">I love winter branches...I don''t know if I''m looking through a window, or if it''s an overlay...either way it works for me.</td>', 'I love winter branches...I don''t know if I''m looking through a window, or if it''s an overlay...either way it works for me.', '2015-03-07 11:03:21.000000', NULL, 1),
(7324732, 1142734, 35804, '<td valign="top">I like this...but  I think I would have liked it even more with a little less of a vignette. I''m losing too much information at the side edges that my eyes would like to see. The light looks so beautiful, that vignette just takes a bit of that away...particularly the shadow of that tree I know is there but gets lost in the darkness that was probably not there pre-processing.</td>', 'I like this...but  I think I would have liked it even more with a little less of a vignette. I''m losing too much information at the side edges that my eyes would like to see. The light looks so beautiful, that vignette just takes a bit of that away...particularly the shadow of that tree I know is there but gets lost in the darkness that was probably not there pre-processing.', '2015-03-07 11:08:55.000000', NULL, 1),
(7324733, 1143158, 30490, '<td valign="top">Lots of interesting detail in this portrait.</td>', 'Lots of interesting detail in this portrait.', '2015-03-07 11:10:06.000000', NULL, 1),
